const serviceExtraBlocks: Record<string, [string, string][]> = {
  "wedding-safa-tying": [
    ["What happens on the day in Bengaluru", "On the day itself, the team arrives with the agreed fabric, accessories and colour direction already confirmed, so nothing needs deciding on the spot. The groom is styled first, in an unhurried session that allows time for kalgi, brooch or feather placement to be checked against the sherwani before the artist moves on. Once the groom's look is finished and approved, attention shifts to close family — parents, siblings and anyone with a more detailed request — followed by the wider baraat in a faster, coordinated batch. For larger groups in Bengaluru, we run more than one artist at once so the queue keeps moving without anyone feeling rushed. A short buffer is built into the schedule for last-minute additions, a missed measurement, or a family member who arrives later than planned. By the time the baraat is ready to depart, every safa has been checked for fold, fit and finish, and the groom's own look has already been reviewed against the day's lighting and the photographer's plan."],
    ["Planning your Bengaluru booking properly", "Booking a wedding safa tying service in Bengaluru works best when you share three things upfront: your date, your venue, and a rough headcount split between groom, family and baraat. From there, we can recommend a realistic artist count and a fabric direction that suits both your outfits and the venue's lighting. It's worth sharing outfit references early too — a photo of the sherwani, or the colour palette for the wider celebration — since this shapes the safa colour recommendation far more usefully than a colour name alone. If your Bengaluru wedding includes more than one function, such as a sangeet or haldi alongside the main ceremony, mention every date together rather than booking them separately; this usually works out both cheaper and easier to schedule, since the same team can plan around all of them at once. We'd also recommend confirming your booking a few weeks ahead during peak wedding season, since Bengaluru dates during the busiest months fill up faster than off-season ones."],
  ],
  "groom-pagdi": [
    ["The groom's styling session in Bengaluru", "The groom's session is always treated as its own appointment, separate from the rest of the wedding party, and is usually scheduled once the sherwani is on and just before the main portrait session begins. In Bengaluru, our artist works through the fold slowly and deliberately, checking the shape against the groom's face and the overall silhouette of the outfit before adding any accessories. A kalgi, brooch, feather or pearl detail is positioned last, and adjusted until it sits in proportion with the rest of the look — this is usually the part that takes the most care, since it's the detail most visible in close-up photographs. We coordinate the exact timing with your photographer wherever possible, so the groom is fully ready right when the portrait session needs him, without a long wait either before or after. Once the groom's pagdi is finished and approved, the artist moves on to family and baraati styling, but the groom's look stays untouched and camera-ready for the rest of the day."],
    ["Booking groom pagdi styling in Bengaluru", "When booking groom pagdi styling in Bengaluru, the most useful thing to share upfront is a reference — a photo, a Pinterest board, or even just a description of the silhouette the groom prefers. From there we can recommend a fabric and colour direction that works with the sherwani and jewellery already chosen. If the groom wants to compare more than one profile before deciding, mention that early, since a trial or a more detailed consultation is easiest to arrange when there's still time before the wedding date. We'd also recommend confirming the exact time the groom needs to be ready by — not just the ceremony time — since this is what determines how early the session needs to start. For Bengaluru bookings during peak wedding season, an earlier confirmation gives more room to finalise colour and accessory choices without last-minute compromises."],
  ],
  "baraati-safa": [
    ["Managing a large baraat in Bengaluru", "For a large baraati group in Bengaluru, the team works in organised batches rather than styling everyone one at a time from a single queue. One repeatable fold and colour direction is agreed in advance, which lets multiple artists work in parallel once the group size calls for it, keeping the overall pace realistic even for sizeable guest lists. A coordinator usually manages the flow — directing guests to the tying area in a sensible order, and keeping a small buffer of fabric and time available for anyone who arrives later than expected. Because the baraat's safas are meant to photograph as one coordinated group, we keep the fold and colour consistent across everyone rather than allowing small variations to creep in guest by guest. Close family can still be given a subtly different or more detailed treatment within the same overall palette, so they remain visually connected to the group while standing slightly apart from the general baraat."],
    ["Booking baraati safa styling in Bengaluru", "For a baraati safa booking in Bengaluru, the two details that matter most are the total guest count and the time available before the procession departs. Both affect how many artists are needed and how the tying schedule is structured on the day. If you're not certain of the exact number yet, a reasonable range is enough to start planning — we'll confirm the final count closer to the date. It's also worth deciding in advance whether the whole baraat wears one uniform look or whether close family gets a distinct but complementary treatment, since this shapes both the fabric order and the tying sequence. Booking a few weeks ahead is especially useful for larger Bengaluru groups during peak wedding season, when artist availability is more limited than usual."],
  ],
  "destination-wedding-safa": [
    ["How a destination assignment runs", "For a destination booking, planning starts long before the travel date — every fabric, accessory and colour choice is locked in and packed ahead of time, since replacements aren't practical once the team is on the move. Once on-site, the team's first task is confirming the preparation space with the venue, followed by the usual sequence of groom, family and baraat, run in the same careful order as any local wedding. Multi-function destination weddings are treated as one connected assignment — if there's a haldi or sangeet alongside the main ceremony, all of them are scheduled within the same trip rather than as separate visits. Property access, road conditions and general travel time to the venue all factor into how early the team arrives, since an early-morning ceremony at a harder-to-reach property needs a bigger buffer than a straightforward hotel booking would."],
    ["Booking a destination safa team for Bengaluru", "The most useful destination quote request includes the property, the route from our base, the full multi-day schedule if there is one, and an approximate guest count for each function. This gives us what we need to plan travel, a realistic arrival buffer, and artist accommodation if the assignment requires an overnight stay. If your celebration spans more than one day, share every date together rather than requesting quotes function by function — a combined destination package is usually more efficient to plan and price than treating each day separately. Because destination bookings involve travel commitments on our side, we'd suggest confirming these further in advance than a local wedding, especially if your dates fall during a busy travel season."],
  ],
  "family-pagdi": [
    ["Styling the wider family in Bengaluru", "Once the groom's pagdi is complete, family styling in Bengaluru begins at a faster, more streamlined pace, though still following a coordinated fold and palette. Close relatives — fathers, brothers, and other immediate family — are often given a slightly more detailed look than the wider group, using a refined fold or a small accessory that sets them subtly apart without competing with the groom. For families choosing two separate colour palettes, one per side, the artist keeps the groups organised so there's no mix-up on the day. We treat comfort as a real consideration here, particularly for older relatives — a softer tension and gentler finish are used whenever comfort is flagged in advance. Children are usually styled toward the end of the family session, since their turbans are simpler and quicker to complete than an adult's more detailed fold."],
    ["Booking family pagdi styling in Bengaluru", "Booking family pagdi styling in Bengaluru works best when you can tell us roughly how many family members need to be styled, and whether both sides of the family want the same palette or two distinct but complementary colours. If any elders have specific comfort needs, mentioning this in advance lets the artist adjust fit and tension accordingly rather than working it out on the day. For families including children, a rough headcount and approximate ages helps us plan time realistically, since younger children's sessions are usually shorter. We'd also suggest deciding early whether close family — parents and siblings — should have a more detailed look than everyone else, since this shapes both the fabric plan and the tying order once the day arrives."],
  ],
  "custom-safa-colours": [
    ["Reviewing colours before the Bengaluru event", "By the time we're on-site for a Bengaluru booking, the colour direction has already been settled — the day itself is about making sure that choice translates properly into the finished look. The artist checks the fabric against the groom's outfit one more time before styling begins, adjusting the fold where needed so the colour reads clearly in both daylight and any indoor lighting the venue has. For weddings using more than one coordinated shade across family and baraat, we keep a clear system for which colour is assigned to which group, so the finished result looks intentional rather than mismatched. If lighting conditions at the Bengaluru venue are unusual — very warm indoor light, or strong outdoor glare — small adjustments are made on the spot to keep the colour looking true rather than distorted in photographs."],
    ["Planning your custom colour direction in Bengaluru", "For a Bengaluru custom colour booking, the fastest route to a good recommendation is sharing what's already fixed — the sherwani, the bride's outfit, or a décor moodboard — since the safa colour is chosen to complement rather than compete with those choices. A physical fabric swatch or a clear reference photo works better than a colour name alone, since shades can read very differently in person. We'd recommend finalising your direction early enough to check the fabric in more than one lighting condition, ideally both daylight and the venue's indoor lighting, so there are no surprises on the day. If you're planning multiple coordinated shades — one for the groom, another for family or baraat — settling this ahead of time also makes it easier for us to plan fabric quantities accurately."],
  ],
};

function makeContent(pageName: string, profile: [string, string, string], isLocation: boolean): PageSeoContent {
  if (isLocation) {
    const heading = LOCATION_HEADING_TEMPLATES[hashIndex(`heading|${pageName}`, LOCATION_HEADING_TEMPLATES.length)](pageName);
    const introduction = LOCATION_INTRO_TEMPLATES[hashIndex(`intro|${pageName}`, LOCATION_INTRO_TEMPLATES.length)](pageName);
    const [t1, t2, t3] = LOCATION_BLOCK_TITLE_SETS[hashIndex(`blocks|${pageName}`, LOCATION_BLOCK_TITLE_SETS.length)](pageName);
    const extra = locationExtraBlocks[pageName.toLowerCase().replace(/&/g, "and").replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "")];
    return {
      heading,
      introduction,
      blocks: [
        { title: t1, body: profile[0] },
        { title: t2, body: profile[1] },
        { title: t3, body: profile[2] },
        ...(extra ? [
          { title: `Venues and season notes for ${pageName}`, body: extra[0] },
          { title: `Choosing the right safa package in ${pageName}`, body: extra[1] },
        ] : []),
      ],
    };
  }
  return {
    heading: `${pageName}: styles, packages and booking guidance`,
    introduction: `A practical guide built around the service terms couples and families use when comparing professional safa tying in Bengaluru.`,
    blocks: [
      { title: "What the service includes", body: profile[0] },
      { title: "Styles, colours and finishing", body: profile[1] },
      { title: "Price, packages and booking", body: profile[2] },
    ],
  };
}

export function getLocationSeoContent(slug: string, name: string): PageSeoContent {
  const profile = locationProfiles[slug];
  if (!profile) throw new Error(`Missing SEO content profile for location: ${slug}`);
  return makeContent(name, profile, true);
}

export function getServiceSeoContent(slug: string, name: string): PageSeoContent {
  const profile = serviceProfiles[slug];
  if (!profile) throw new Error(`Missing SEO content profile for service: ${slug}`);
  const base = makeContent(name, profile, false);
  const extra = serviceExtraBlocks[slug];
  if (!extra) return base;
  return { ...base, blocks: [...base.blocks, ...extra.map(([title, body]) => ({ title, body }))] };
}
